    for step in result.steps:
        assert step.divergences == [], (
            f"unexpected divergence at step {step.step_index}: "
            f"action={step.action_dict} "
            f"{[(d.field, d.py_value, d.rust_value, d.known_gap) for d in step.divergences]}"
        )


