def test_rust_lose_life_cross_controller_routing():
    """Rust regression pin: source owned by p1 -- the source-finder
    walks both players' five tracked zones + stack per
    state_ops_resolve.rs:3675-3700, finds source.controller=1, and
    p1 (the source's controller) loses life. Pins cross-controller
    routing: a LoseLife effect controlled by p1 affects p1's life
    even when active_player=p0 (distinguishing pin vs sister
    each_opponent_loses_life which would route the loss to p0
    instead).
    """
    rust_state, _source_id = _build_rust_lose_life_state(
        amount=2, source_owner=1,
    )
    life_before = list(rust_state.life_totals)
    rust_state.resolve_top_of_stack()
    life_after = list(rust_state.life_totals)
    # p1 (source controller) loses 2; p0 (opponent) unchanged.
    # This is the distinguishing observable vs each_opponent_loses_life:
    # each_opponent would have hit p0 (the opponent of p1).
    assert life_after[1] == life_before[1] - 2, (
        f"p1 (source controller) should lose 2 life; "
        f"before={life_before[1]}, after={life_after[1]}"
    )
    assert life_after[0] == life_before[0], (
        f"p0 (opponent of p1) should be unchanged -- LoseLife "
        f"affects controller, not opponents (distinguishing pin vs "
        f"each_opponent_loses_life); "
        f"before={life_before[0]}, after={life_after[0]}"
    )


def test_rust_lose_life_saturating_at_low_life():
    """Rust regression pin: when amount > current life, life saturates
    at 0 (Rust's saturating_sub semantics; no negative-overflow). The
    SBA-driven loss-detection runs separately on the resolve loop --
    this pin only verifies the arithmetic clamps. Pins the
    saturating_sub at state_ops_resolve.rs:3666-.
    """
    rust_state, _source_id = _build_rust_lose_life_state(
        amount=99, source_owner=0,
    )
    life_before_p0 = rust_state.life_totals[0]
    assert life_before_p0 < 99  # confirm we're really overshooting (default 20)
    rust_state.resolve_top_of_stack()
    life_after_p0 = rust_state.life_totals[0]
    # Saturating sub clamps to 0 (not negative), but engine may also
    # bottom out at 0 via SBA. Either way, post-resolve p0's life is
    # less than or equal to 0.
    assert life_after_p0 <= 0, (
        f"p0 life should be <= 0 after losing 99 from {life_before_p0}; "
        f"got {life_after_p0}"
    )


def _build_rust_untap_target_other_permanent_state(
    source_owner: int = 0, target_owner: int = 0,
):
    """Helper: build a Rust state with a source carrier creature on
    ``source_owner``'s bf carrying an ETB trigger that fires
    UntapTargetOtherPermanent, PLUS a tapped non-source permanent
    (Bear) on ``target_owner``'s bf so Rust's bf_iter_etb_sorted
    picker has an eligible target. Returns
    (rust_state, source_id, target_permanent_id).

    Round-24 BLOCKED-BRIDGE-ARM helper. Mirrors the round-23
    `_build_rust_untap_target_state` shape; key difference is the
    target filter (any-permanent-not-source vs creature-only).
    """
    from mtg_bot.parity.cross_engine import (
        DeckSpec, build_rust_state,
    )

    spec = DeckSpec(card_defs=(), p0_library=(), p1_library=())
    rust_state = build_rust_state(spec)
    ZONE_BATTLEFIELD = 2
    # Seat the bait permanent FIRST so it has the lower ETB timestamp
    # and Rust's bf_iter_etb_sorted picks it before scanning the
    # source itself.
    target_permanent_id = rust_state.register_and_inject_object(
        {
            "name": "UntapOther Bait Bear (3/3)",
            "card_types": ["Creature"],
            "mana_cost": {"generic": 2, "G": 1},
            "effects": [],
            "power": 3,
            "toughness": 3,
        },
        target_owner,
        ZONE_BATTLEFIELD,
    )
    # Tap it explicitly so it's eligible (filter: tapped != source).
    assert rust_state.tap_object(target_permanent_id) is True
    source_id = rust_state.register_and_inject_object(
        {
            "name": "UntapTargetOtherPermanent ETB Carrier",
            "card_types": ["Creature"],
            "mana_cost": {"U": 1, "generic": 1},
            "power": 1,
            "toughness": 2,
            "effects": [],
            "triggered_abilities": [
                {
                    "event": "enters",
                    "predicate": {"kind": "source_is_self"},
                    "effect": {"kind": "untap_target_other_permanent"},
                }
            ],
        },
        source_owner,
        ZONE_BATTLEFIELD,
    )
    return rust_state, source_id, target_permanent_id


def test_rust_untap_target_other_permanent_basic_untaps_other_creature():
    """Rust regression pin: basic untap-target-other-permanent --
    Rust's bf_iter_etb_sorted picker walks both bfs, skips the
    source itself, and picks the FIRST tapped non-source permanent.
    Pre-injected Bear (lower ETB stamp) gets untapped via
    Arc::make_mut. Pins state_ops_resolve.rs:7022-7054's bf-walk +
    skip-source clause + tapped filter + obj.tapped = false flip.
    """
    rust_state, source_id, target_permanent_id = (
        _build_rust_untap_target_other_permanent_state(
            source_owner=0, target_owner=0,
        )
    )
    assert rust_state.stack_size() == 1
    # Pre-resolve: target is tapped, source is untapped.
    assert _is_tapped(rust_state, target_permanent_id) is True
    assert _is_tapped(rust_state, source_id) is False
    rust_state.resolve_top_of_stack()
    assert rust_state.stack_size() == 0
    # Post-resolve: target is untapped, source unchanged.
    assert _is_tapped(rust_state, target_permanent_id) is False, (
        f"target permanent {target_permanent_id} should be untapped; "
        f"tapped={_is_tapped(rust_state, target_permanent_id)}"
    )
    assert _is_tapped(rust_state, source_id) is False


